/* Same interface for the real API and the explicitly isolated offline preview. */
'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'NT$ '+Number(n||0).toLocaleString('zh-TW');
const preview=Boolean(window.GUGU_PREVIEW);
const storage={get(k,fallback){try{return JSON.parse(localStorage.getItem('gugu:'+k))??fallback}catch{return fallback}},set(k,v){try{localStorage.setItem('gugu:'+k,JSON.stringify(v))}catch{}},remove(k){try{localStorage.removeItem('gugu:'+k)}catch{}}};
const statusNames={pending:'等待接單',accepted:'已接單',preparing:'製作中',ready:'可以取餐',completed:'已取餐',cancelled:'已取消',rejected:'未接單',no_show:'未取餐'};
const roleNames={owner:'管理者',cashier:'櫃台',kitchen:'廚房'};
const state={store:null,pendingOrder:storage.get('pending',null),products:[],slots:[],day:'',category:'全部',search:'',cart:storage.get('cart',[]),area:'shop',user:null,csrf:'',staffTab:'orders',orders:[],orderTotal:0,offset:0,kdsFilter:'active',kdsSearch:'',staffDay:'',staffProducts:[],report:null,auditOffset:0,track:null,trackToken:'',sound:false,seenOrders:new Set(),loadedOrders:false,queueDates:[],seenQueue:new Set(),connected:true,cartVisible:false,dialogProduct:null};
if(!Array.isArray(state.cart))state.cart=[];
state.cart=state.cart.filter(x=>x&&typeof x.product_id==='string'&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=20&&Number.isInteger(x.unit_price)&&x.unit_price>=0&&Array.isArray(x.labels)&&x.choices&&typeof x.choices==='object'&&Number.isInteger(x.version)).slice(0,20);
let toastTimer,refreshing=false,lastFocus=null;
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4300)}
function link(area){return preview?(area==='shop'?'#shop':area==='staff'?'#staff':'#display'):(area==='shop'?'/':area==='staff'?'/staff/':'/display/')}
function displayDate(d){return new Date(d+'T12:00:00+08:00').toLocaleDateString('zh-TW',{month:'numeric',day:'numeric',weekday:'short',timeZone:'Asia/Taipei'})}
function clock(t){return new Date(t).toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Taipei',hour12:false})}
function dayPlus(d,n){const dt=new Date(d+'T12:00:00Z');dt.setUTCDate(dt.getUTCDate()+n);return dt.toISOString().slice(0,10)}
function uid(){return crypto.randomUUID?crypto.randomUUID():'10000000-1000-4000-8000-100000000000'.replace(/[018]/g,c=>(c^crypto.getRandomValues(new Uint8Array(1))[0]&15>>c/4).toString(16))}
function connection(ok){state.connected=ok;const e=$('#connection');if(e)e.innerHTML=`<i class="status-dot ${ok?'':'off'}"></i>${ok?(preview?'本機體驗':'已連線'):'連線中斷・正在重試'}`}
async function api(path,method='GET',body){
 if(preview)return window.DemoAPI(path,method,body);
 let r;
 try{r=await fetch(path,{method,credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-Requested-With':'Gugu',...(state.csrf?{'X-CSRF-Token':state.csrf}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(15000)})}catch(err){connection(false);throw Object.assign(new Error('連線不穩，尚未確認送單結果。請保留此頁面後重試，不要重新建立訂單。'),{status:0})}
 connection(true);
 const data=await r.json().catch(()=>({detail:'系統回應異常，請稍後再試'}));
 if(!r.ok)throw Object.assign(new Error(typeof data.detail==='string'?data.detail:'資料格式不正確'),{status:r.status});
 return data;
}
function demoBanner(){if(state.store?.mode!=='demo')return'';return `<div class="demo-banner"><strong>${preview?'互動體驗版':'測試系統'}</strong> · 非店家官方點餐入口 · 售價／規格皆為測試資料 · 不會傳送給店家${preview?' · 僅儲存在此瀏覽器':''}</div>`}
function header(active='shop'){const s=state.store||{};return `${demoBanner()}<header class="topbar"><a href="${link('shop')}" class="brand" aria-label="回到菜單"><div class="brand-mark">穀</div><div><strong>${esc(s.name||'穀穀')}</strong><span>${esc(s.branch||'台中學府總店')}</span></div></a><nav class="topnav" aria-label="主要導覽"><a class="${active==='shop'?'active':''}" href="${link('shop')}">點餐</a><button data-action="recent" class="${active==='track'?'active':''}">我的訂單</button><a class="${active==='staff'?'active':''}" href="${link('staff')}">店家工作台</a><a class="desktop-nav ${active==='display'?'active':''}" href="${link('display')}">取餐看板</a></nav></header>`}
function footer(){const s=state.store;return `<footer class="footer"><p>${esc(s.address)}<br>${s.mode==='demo'?'店家資訊僅供提案辨識；正式營業時間與價格待確認。':'聯絡電話：'+esc(s.phone)}</p><div><p>到店自取 · 現場付現 · 台灣時間</p><button data-action="privacy">訂購與個資說明</button> · <span class="connection" id="connection"><i class="status-dot"></i>${preview?'本機體驗':'已連線'}</span></div></footer>`}
async function init(){
 try{
  state.store=await api('/api/store');state.day=state.store.today;state.staffDay=state.day;
  await route();
 }catch(e){$('#app').innerHTML=`<div class="loading"><h2>暫時無法連線</h2><p>${esc(e.message)}</p><button class="btn" data-action="reload">重新整理</button></div>`}
}
async function route(){
 closeDialog();document.body.classList.remove('display-mode');
 const hash=location.hash;
 if(hash.startsWith('#order=')){state.area='track';state.trackToken=hash.slice(7);return loadTrack()}
 state.area=(preview?hash.startsWith('#staff'):location.pathname.startsWith('/staff'))?'staff':(preview?hash.startsWith('#display'):location.pathname.startsWith('/display'))?'display':'shop';
 if(state.area==='staff')return loadStaff();
 if(state.area==='display')return loadDisplay();
 await loadShop();
}
async function loadShop(){
 const [menu,slots]=await Promise.all([api('/api/menu?day='+state.day),api('/api/slots?day='+state.day)]);
 state.products=menu.products;state.slots=slots.slots;renderShop();
}
function dateOptions(selected=state.day){let out='';for(let i=0;i<=state.store.advance_days;i++){const d=dayPlus(state.store.today,i);out+=`<option value="${d}" ${d===selected?'selected':''}>${i===0?'今天 · ':i===1?'明天 · ':''}${displayDate(d)}</option>`}return out}
function renderShop(){
 document.title='穀穀・今天也好好吃飯';const s=state.store;
 $('#app').innerHTML=`${header()}<main id="main" class="page"><div class="shop-layout"><section><div class="hero"><div><div class="eyebrow">GOOD FOOD, AT YOUR OWN PACE</div><h1>今天，也好好吃飯。</h1><p>${esc(s.announcement)}</p></div><div class="hero-seal">好好吃飯　穀穀</div></div>
 ${!s.accepting?'<div class="notice error" style="margin-top:18px">目前未開放新訂單（休息中、暫停接單或尚未完成上線確認）。已成立的訂單仍可正常查詢。</div>':''}
 ${state.pendingOrder?'<div class="notice" style="margin-top:18px">你有一筆送單結果尚未確認。<button class="link-button" data-action="retry-order">查詢／重試同一筆訂單</button></div>':''}
 <div class="pickup-strip"><div class="pickup-info"><strong>外帶自取</strong><span>預留 ${s.prep_minutes} 分鐘準備 · 現場付現</span></div><label><span class="hidden">取餐日期</span><select id="pickup-day" aria-label="取餐日期">${dateOptions()}</select></label></div>
 <div class="section-head"><h2>今日菜單 <small id="menu-count"></small></h2><input class="search" id="menu-search" type="search" placeholder="找想吃的餐點" value="${esc(state.search)}" aria-label="搜尋餐點"></div><div class="category-list" id="categories"></div><div class="menu-grid" id="menu-grid"></div>
 <div class="how-it-works"><div><strong><span class="step-num">01</span> 選今天想吃的</strong><p>飯量、口味，一次選好。</p></div><div><strong><span class="step-num">02</span> 選擇取餐時間</strong><p>送出後等店家確認。</p></div><div><strong><span class="step-num">03</span> 看號碼，來取餐</strong><p>完成通知看訂單頁面。</p></div></div></section><aside class="cart-panel ${state.cartVisible?'':'mobile-hidden'}" id="cart-panel" aria-label="購物車"></aside></div>${footer()}</main><div class="mobile-cart" id="mobile-cart"></div>`;
 renderCategories();renderMenu();renderCart();
}
function renderCategories(){const cats=['全部',...new Set(state.products.map(p=>p.category))];$('#categories').innerHTML=cats.map(c=>`<button class="chip ${c===state.category?'active':''}" data-action="category" data-value="${esc(c)}">${esc(c)}</button>`).join('')}
function renderMenu(){
 const products=state.products.filter(p=>(state.category==='全部'||p.category===state.category)&&p.name.toLowerCase().includes(state.search.toLowerCase()));
 $('#menu-count').textContent=products.length+' 道';
 $('#menu-grid').innerHTML=products.length?products.map(p=>{const sold=p.sold_out||p.remaining<=0;const mark=p.category.includes('魚')?'魚':p.category.includes('蔬')?'蔬':p.kind==='addon'?'添':'肉';return `<article class="meal-card"><div class="meal-top"><span class="meal-index">${String(state.products.indexOf(p)+1).padStart(2,'0')}</span><span class="food-mark" aria-hidden="true">${mark}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div class="meal-bottom"><div class="price"><small>NT$</small>${p.price}</div>${sold?'<span class="sold">今日已售完</span>':`<button class="add-btn" data-action="product" data-id="${esc(p.id)}" aria-label="選擇${esc(p.name)}" ${!state.store.accepting?'disabled':''}>＋</button>`}</div>${!sold&&p.remaining<=5?`<span class="sold" style="margin-top:5px">這個取餐日剩 ${p.remaining} 份</span>`:''}</article>`}).join(''):'<div class="empty">找不到符合的餐點，試試其他關鍵字。</div>';
}
function cartTotal(){return state.cart.reduce((s,i)=>s+i.unit_price*i.quantity,0)}
function cartQty(){return state.cart.reduce((s,i)=>s+i.quantity,0)}
function cartRows(){return state.cart.map((i,n)=>`<div class="cart-row"><div class="cart-row-top"><strong>${esc(i.name)}</strong><span>${money(i.unit_price*i.quantity)}</span></div><div class="details">${esc(i.labels.join(' · '))}${i.note?' · '+esc(i.note):''}</div><div class="cart-row-bottom"><div class="qty-control"><button data-action="cart-minus" data-index="${n}" aria-label="減少${esc(i.name)}數量">−</button><span>${i.quantity}</span><button data-action="cart-plus" data-index="${n}" aria-label="增加${esc(i.name)}數量">＋</button></div><button class="link-button" data-action="cart-remove" data-index="${n}" aria-label="移除${esc(i.name)}">移除</button></div></div>`).join('')}
function renderCart(){
 const panel=$('#cart-panel');if(!panel)return;
 panel.innerHTML=`<div class="eyebrow muted" style="margin-bottom:10px">YOUR LUNCH</div><h2>這一餐</h2><p class="cart-caption">${displayDate(state.day)} · 外帶自取</p>${state.cart.length?cartRows():'<div class="cart-empty"><span class="empty-bowl" aria-hidden="true"></span>先選一道喜歡的餐點吧。<br><small>選好再決定幾點來取。</small></div>'}<div class="cart-total"><span>共 ${cartQty()} 份</span><strong>${money(cartTotal())}</strong></div><button class="btn full" data-action="checkout" ${!state.cart.length||!state.store.accepting?'disabled':''}>選擇時間，確認訂單 <span>→</span></button><p class="cart-note">不需要註冊 · 餐點完成再到店<br>${state.store.mode==='demo'?'以上金額為測試資料，不是店內正式價格。':'尚未送出前不會成立訂單。'}</p>`;
 $('#mobile-cart').innerHTML=`<div class="cart-amount"><small>共 ${cartQty()} 份</small>${money(cartTotal())}</div><button class="btn" data-action="mobile-cart" ${!state.cart.length?'disabled':''}>查看這一餐 <span>→</span></button>`;
}
function saveCart(){storage.set('cart',state.cart);renderCart()}
function openDialog(content){lastFocus=document.activeElement;const d=$('#modal');d.innerHTML=content;if(!d.open)d.showModal();d.scrollTop=0}
function closeDialog(){const d=$('#modal');if(d?.open){d.close();if(lastFocus?.isConnected)lastFocus.focus()}}
function modalHead(title,kicker=''){return `<div class="modal-head"><div>${kicker?`<div class="eyebrow muted" style="margin-bottom:7px">${esc(kicker)}</div>`:''}<h2>${esc(title)}</h2></div><button type="button" class="close" data-action="close" aria-label="關閉">×</button></div>`}
function openProduct(id){
 const p=state.products.find(x=>x.id===id);if(!p)return;state.dialogProduct=p;
 openDialog(`<form id="product-form">${modalHead(p.name,p.category)}<div class="modal-body"><p class="help">${esc(p.description)}</p>${p.options.map(g=>`<div class="option-group"><fieldset><legend>${esc(g.name)} ${g.required?'<small class="muted">必選</small>':''}</legend><div class="option-grid">${g.choices.map((c,n)=>`<label class="option-label"><input type="radio" name="choice-${esc(g.id)}" value="${esc(c.id)}" ${n===0?'checked':''} ${g.required?'required':''}><span>${esc(c.name)}${c.price?'<small> ＋'+c.price+'</small>':''}</span></label>`).join('')}</div></fieldset></div>`).join('')}<label class="field"><span>這份餐點的備註</span><input name="note" maxlength="100" placeholder="例如：醬料另外放（由店家確認）"></label><p class="help">有食物過敏，請先與店家確認能否供應。備註不代表店家已接受客製需求。</p><div class="between"><span>份數</span><div class="qty-control"><button type="button" data-action="product-minus" aria-label="減少份數">−</button><span id="product-qty">1</span><button type="button" data-action="product-plus" aria-label="增加份數">＋</button></div></div><p class="error-text" id="dialog-error"></p></div><div class="modal-foot"><button class="btn full" type="submit">加入這一餐 · <span id="product-price">${money(p.price+(p.options.reduce((a,g)=>a+(g.choices[0]?.price||0),0)))}</span></button></div></form>`);
}
function productSelections(){const form=$('#product-form'),p=state.dialogProduct;let price=p.price;const choices={},labels=[];for(const g of p.options){const selected=form.querySelector(`input[name="choice-${g.id}"]:checked`)?.value;const c=g.choices.find(c=>c.id===selected);if(c){choices[g.id]=c.id;labels.push(c.name);price+=c.price}}return{choices,labels,price,qty:Number($('#product-qty').textContent)}}
function updateProductPrice(){const v=productSelections();$('#product-price').textContent=money(v.price*v.qty)}
function addProduct(form){if(state.pendingOrder)throw new Error('前一筆送單結果尚未確認，請先回到菜單查詢該筆訂單');const p=state.dialogProduct,v=productSelections();if(cartQty()+v.qty>40)throw new Error('每筆最多 40 份，大量訂餐請先與店家聯繫');const note=new FormData(form).get('note').trim();const same=state.cart.find(i=>i.product_id===p.id&&JSON.stringify(i.choices)===JSON.stringify(v.choices)&&i.note===note&&i.version===p.version);if(same&&same.quantity+v.qty<=20)same.quantity+=v.qty;else{if(state.cart.length>=20)throw new Error('一筆訂單最多 20 種組合');state.cart.push({product_id:p.id,name:p.name,quantity:v.qty,unit_price:v.price,choices:v.choices,labels:v.labels,note,version:p.version})}saveCart();closeDialog();toast('已加入 '+p.name)}
async function openCheckout(){
 if(!state.cart.length)return;
 if(state.pendingOrder){await retryOrder();return}
 state.slots=(await api('/api/slots?day='+state.day)).slots;
 const available=state.slots.filter(s=>s.remaining>=cartQty());
 openDialog(`<form id="checkout-form">${modalHead('確認這一餐','PICK UP & ENJOY')}<div class="modal-body"><div class="notice ${available.length?'good':'error'}">${displayDate(state.day)} · 外帶自取${available.length?'':'：目前沒有能容納這筆訂單的時段，請改選日期或減少份數。'}</div>${state.store.mode==='demo'?'<p class="help">正在體驗測試流程，請勿填寫真實個資。下單不會通知真實店家。</p>':''}<label class="field"><span>取餐時間</span><select name="slot" required ${!available.length?'disabled':''}>${available.length?available.map(s=>`<option value="${s.time}">${s.time} · 尚可接 ${s.remaining} 份</option>`).join(''):'<option>沒有可預約時段</option>'}</select></label><div class="field-grid"><label class="field"><span>怎麼稱呼你</span><input name="name" autocomplete="given-name" maxlength="24" required value="${state.store.mode==='demo'?'體驗顧客':''}" placeholder="姓名或稱呼"></label><label class="field"><span>聯絡電話</span><input name="phone" type="tel" autocomplete="tel" maxlength="18" required value="${state.store.mode==='demo'?'0900000000':''}" placeholder="09xx xxx xxx"></label></div><label class="field" style="margin-top:18px"><span>整筆訂單備註</span><textarea name="note" maxlength="200" placeholder="例如：不需要餐具。客製需求須由店家確認。"></textarea></label><div class="cart-total"><span>${cartQty()} 份 · 現場付現</span><strong>${money(cartTotal())}</strong></div><label class="check"><input name="consent" type="checkbox" required><span>我已閱讀下方訂購與個資說明，並同意提供聯絡資料供此次訂餐使用。</span></label><details style="margin-top:12px"><summary>訂購與個資說明</summary><p class="help">${privacySummary()}</p></details><p class="error-text" id="dialog-error" aria-live="polite"></p></div><div class="modal-foot"><button type="button" class="btn outline" data-action="close">再確認一下</button><button type="submit" class="btn" ${!available.length?'disabled':''}>${state.store.mode==='demo'?'送出測試訂單':'確認送出訂單'}</button></div></form>`);
}
function privacySummary(){return `僅收集稱呼、電話與餐點備註，用於接單、聯繫及交付餐點；不使用於行銷。僅具權限的店員可查看完整聯絡電話，取餐看板不顯示姓名或電話。完成或取消的訂單於 ${state.store.privacy_days} 天後移除聯絡與文字資料；備份另依店家訂定的輪替制度刪除。你可聯繫店家提出資料查詢或刪除需求。送出後，店家須在 ${state.store.accept_timeout} 分鐘內接單；逾時自動取消，不會收款。接單前可自行取消，接單後請洽店家。此系統僅記錄現場現金收款，不會線上扣款。訂單連結含私人查詢憑證，請勿公開分享。${state.store.mode==='demo'?'目前為未經店家驗收的提案／測試環境，不成立真實餐點交易，請勿提供真實個資。':''}`}
async function submitOrder(form){if(state.pendingOrder)return sendStoredOrder(state.pendingOrder);const f=new FormData(form);const payload={idempotency_key:uid(),name:String(f.get('name')),phone:String(f.get('phone')),day:state.day,slot:String(f.get('slot')),items:state.cart.map(i=>({product_id:i.product_id,quantity:i.quantity,choices:i.choices,note:i.note,version:i.version})),note:String(f.get('note')),consent:f.get('consent')==='on'};state.pendingOrder=payload;storage.set('pending',payload);await sendStoredOrder(payload)}
async function retryOrder(){const p=state.pendingOrder;if(!p)return;await sendStoredOrder(p)}
async function sendStoredOrder(payload){try{const order=await api('/api/orders','POST',payload);state.pendingOrder=null;storage.remove('pending');state.cart=[];storage.set('cart',[]);let recent=storage.get('recent',[]);recent=[{token:order.token,number:order.number,day:order.day},...recent.filter(x=>x.token!==order.token)].slice(0,20);storage.set('recent',recent);closeDialog();state.track=order;state.trackToken=order.token;state.area='track';location.hash='order='+order.token;renderTrack(order);toast('訂單已送出，請等店家確認')}catch(e){if(e.status>=400&&e.status<500&&e.status!==429){state.pendingOrder=null;storage.remove('pending')}else{const f=$('#checkout-form');if(f){f.querySelectorAll('input,select,textarea').forEach(x=>x.disabled=true);const b=f.querySelector('button[type=submit]');if(b)b.textContent='重試原筆訂單'}}throw e}}
async function loadTrack(){
 try{state.track=await api('/api/order/track','POST',{token:state.trackToken});renderTrack(state.track)}catch(e){$('#app').innerHTML=`${header('track')}<main id="main" class="page"><div class="empty"><h2>暫時無法讀取訂單</h2><p>${esc(e.message)}</p><button class="btn" data-action="refresh-track">再試一次</button></div></main>`}
}
function trackContents(o){const steps=['pending','accepted','preparing','ready'];const idx=o.status==='completed'?4:steps.indexOf(o.status);return `<div class="ticket"><div class="ticket-top"><div class="eyebrow">${o.demo?'TEST ORDER · 測試取餐號碼':'YOUR PICKUP NUMBER'}</div><div class="ticket-number mono">${esc(o.number)}</div><p><strong>${esc(statusNames[o.status])}</strong></p><p class="help">${displayDate(o.day)} ${o.slot} 取餐 · ${esc(state.store.branch)}</p></div><div class="ticket-body">${o.status==='ready'?'<div class="notice good">餐點好了。請到櫃台報取餐號碼，確認付款後領取餐點。</div>':''}${o.status==='pending'?`<p class="help">這不是立即成立的取餐承諾；等待店家接單中。${clock(o.expires_at)} 前未確認將自動取消。頁面每 5 秒更新，請保留此頁。</p>`:''}${['cancelled','rejected','no_show'].includes(o.status)?`<div class="notice error">這筆訂單已結束。${o.payment==='refunded'?'店員已登記現金退款。':o.payment==='unpaid'?'沒有收款。':''}</div>`:`<div class="progress">${['送出訂單','店家確認','正在製作','前往取餐'].map((t,i)=>`<div class="step ${i<=idx?'done':''}">${t}</div>`).join('')}</div>`}<ul class="order-items">${o.items.map(i=>`<li><div class="between"><strong>${esc(i.name)} × ${i.quantity}</strong><span>${money(i.line_total)}</span></div><small>${esc(i.labels.join(' · '))}${i.note?' · '+esc(i.note):''}</small></li>`).join('')}</ul>${o.note?`<div class="order-note">${esc(o.note)}</div>`:''}<div class="cart-total"><span>${o.payment==='paid'?'已收現金':o.payment==='refunded'?'現金已退還':'現場應付'}</span><strong>${money(o.total)}</strong></div><p class="help">${esc(o.name)} · ${esc(o.phone||'')}<br>訂單查詢連結為私人憑證，請自行保存，勿公開分享。</p><div class="flex wrap"><button class="btn secondary small" data-action="copy-order">複製訂單連結</button>${!preview?'<button class="btn outline small" data-action="order-qr">查看取餐 QR Code</button>':''}${o.status==='pending'?'<button class="btn danger small" data-action="cancel-order">取消這筆訂單</button>':''}<a class="btn outline small" href="${link('shop')}">回到菜單</a></div><div class="divider"></div><details><summary>訂單紀錄</summary><ul class="timeline">${o.events.slice().reverse().map(e=>`<li><strong>${esc(e.detail||e.action)}</strong>${clock(e.at)}</li>`).join('')}</ul></details><p class="connection" id="connection" style="margin:15px 0 0"><i class="status-dot ${state.connected?'':'off'}"></i>${state.connected?'已更新 '+clock(new Date()):'連線中斷・正在重試'}</p></div></div>`}
function renderTrack(o){document.title=o.number+' · 穀穀取餐';$('#app').innerHTML=`${header('track')}<main id="main" class="page"><div class="track-layout"><div class="page-title"><h1>這一餐，幫你記好了。</h1><p>${o.demo?'測試流程不會通知店家，請勿憑此號碼向真實店家取餐。':'店家確認後，依約定時間到店取餐。'}</p></div><div id="ticket-content">${trackContents(o)}</div></div></main>`}
function showRecent(){const recent=storage.get('recent',[]);openDialog(`${modalHead('我的訂單')}<div class="modal-body">${recent.length?recent.map(o=>`<a class="panel between" href="#order=${esc(o.token)}" data-action="close"><div><strong class="mono">${esc(o.number)}</strong><small class="muted"> · ${esc(o.day)}</small></div><span>查看進度 →</span></a>`).join(''):'<div class="empty">這個瀏覽器還沒有訂單。<br><small>在其他裝置下的單，請使用當時保存的私人訂單連結。</small></div>'}<p class="help">只列出這個瀏覽器保存的訂單。不提供以電話直接查詢，避免他人讀取你的訂單。</p></div>`)}
async function loadStaff(){
 try{const me=await api('/api/auth/me');state.user=me.user;state.csrf=me.csrf;renderStaffShell();await loadStaffTab()}catch(e){if(e.status===401||preview){state.user=null;renderLogin()}else throw e}
}
function renderLogin(){document.title='店家登入 · 穀穀';$('#app').innerHTML=`${header('staff')}<main id="main" class="page"><div class="login-wrap"><div class="page-title"><div class="eyebrow muted">GUGU / STORE WORKSPACE</div><h1 style="margin-top:10px">今天，開店了。</h1><p>訂單、餐點和取餐進度，都在這裡。</p></div><form class="login-card" id="login-form">${preview?'<div class="notice">這是本機體驗工作台，沒有真實店家資料；切換身分只是預覽，不是正式帳號登入。</div><label class="field"><span>體驗身分</span><select name="role"><option value="owner">店家管理者</option><option value="cashier">櫃台人員</option><option value="kitchen">廚房人員</option></select></label>':'<label class="field"><span>帳號</span><input name="username" autocomplete="username" required placeholder="店家帳號"></label><label class="field"><span>密碼</span><input name="password" type="password" autocomplete="current-password" required placeholder="請輸入密碼"></label>'}<p class="error-text" id="login-error"></p><button type="submit" class="btn full">${preview?'進入體驗工作台':'登入工作台'} →</button><p class="help" style="margin:18px 0 0">${preview?'顧客點餐、店家接單共用這個瀏覽器的測試資料。不同裝置不會同步。':'第一次使用：請查看啟動終端機顯示的隨機帳號密碼。系統沒有共用預設密碼。'}</p></form></div></main>`}
function staffTabs(){const role=state.user.role;return [['orders','接單工作台'],...(['owner','cashier'].includes(role)?[['inventory','菜單與庫存']]:[]),...(role==='owner'?[['reports','營業報表'],['settings','營業設定'],['users','人員權限'],['audit','操作紀錄']]:[])]}
function renderStaffShell(){document.title='店家工作台 · 穀穀';$('#app').innerHTML=`${header('staff')}<main id="main" class="page"><div class="page-title between"><div><div class="eyebrow muted">STORE WORKSPACE</div><h1 style="margin-top:9px">把每一餐，準時交到手上。</h1><p>${esc(state.user.name)} · ${roleNames[state.user.role]} <span id="connection" class="connection" style="margin-left:10px"><i class="status-dot"></i>${preview?'本機體驗':'已連線'}</span></p></div><div class="flex"><button class="btn outline small mobile-hide" data-action="password">變更密碼</button><button class="btn outline small" data-action="logout">登出</button></div></div><nav class="staff-tabs" aria-label="工作台功能">${staffTabs().map(([id,name])=>`<button class="staff-tab ${state.staffTab===id?'active':''}" data-action="staff-tab" data-tab="${id}">${name}</button>`).join('')}</nav><section id="staff-content"></section></main>`}
async function loadStaffTab(){
 if(!staffTabs().some(x=>x[0]===state.staffTab))state.staffTab='orders';
 $$('.staff-tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===state.staffTab));
 const root=$('#staff-content');root.innerHTML='<div class="empty">正在讀取…</div>';
 if(state.staffTab==='orders'){root.innerHTML=`<div class="toolbar"><input type="date" id="staff-day" value="${state.staffDay}" aria-label="查看訂單日期"><input type="search" class="search" id="order-search" placeholder="搜尋取餐號碼或稱呼" value="${esc(state.kdsSearch)}" aria-label="搜尋訂單"><button class="btn outline small" data-action="refresh-staff">重新整理</button><button class="btn outline small" data-action="sound" id="sound-button">${state.sound?'提示音已開啟':'開啟新單提示音'}</button><div class="spacer"></div>${state.user.role!=='kitchen'?`<button class="btn ${state.store.paused?'secondary':'outline'} small" data-action="pause" id="pause-button">${state.store.paused?'恢復接單':'暫停接單'}</button>`:''}<a class="btn secondary small" href="${link('display')}" ${!preview?'target="_blank" rel="noopener"':''}>取餐看板 ↗</a></div><div id="queue-other-dates"></div><div id="kds-summary" class="kds-summary"></div><div id="order-grid" class="orders-grid"></div><div id="order-pagination"></div><p class="help" style="margin-top:20px">每 3 秒更新。頁面開啟並啟用聲音後，才會播放新單提示。切到背景或鎖定手機時，請勿依賴此頁通知。</p>`;await refreshOrders();}
 if(state.staffTab==='inventory'){state.staffProducts=(await api('/api/staff/products?day='+state.staffDay)).products;renderInventory()}
 if(state.staffTab==='reports'){state.report=await api('/api/staff/reports?day='+state.staffDay);renderReports()}
 if(state.staffTab==='settings'){state.store=await api('/api/store');renderSettings()}
 if(state.staffTab==='users'){state.staffUsers=(await api('/api/staff/users')).users;renderUsers()}
 if(state.staffTab==='audit'){const data=await api('/api/staff/audit?offset='+state.auditOffset);renderAudit(data.events)}
}
async function refreshOrders(){
 const [result,queue]=await Promise.all([api(`/api/staff/orders?day=${state.staffDay}&offset=${state.offset}&limit=100`),api('/api/staff/pending-dates')]);
 state.queueDates=queue.dates;
 const extra=queue.dates.filter(d=>d.day!==state.staffDay&&!state.seenQueue.has(d.day+':'+d.latest));
 if(state.loadedOrders&&extra.length&&state.sound)beep();
 queue.dates.forEach(d=>state.seenQueue.add(d.day+':'+d.latest));
 const incoming=result.orders.filter(o=>o.status==='pending'&&!state.seenOrders.has(o.public_id));
 if(state.loadedOrders&&incoming.length&&state.sound)beep();
 result.orders.forEach(o=>state.seenOrders.add(o.public_id));state.loadedOrders=true;
 state.orders=result.orders;state.orderTotal=result.total;renderOrders();
}
function renderOrders(){
 if(!$('#order-grid'))return;
 const queue=$('#queue-other-dates');if(queue)queue.innerHTML=state.queueDates.filter(d=>d.day!==state.staffDay).map(d=>`<div class="notice">${displayDate(d.day)} 還有 ${d.pending} 筆預約等待接單。<button class="link-button" data-action="queue-date" data-day="${d.day}">前往處理 →</button></div>`).join('');
 const filters=[['active','進行中'],['pending','待接單'],['preparing','製作中'],['ready','待取餐'],['all','全部']];
 const count=k=>state.orders.filter(o=>k==='all'||k==='active'?k==='all'||['pending','accepted','preparing','ready'].includes(o.status):o.status===k).length;
 $('#kds-summary').innerHTML=filters.map(([id,name])=>`<button class="kds-filter ${state.kdsFilter===id?'active':''}" data-action="kds-filter" data-value="${id}">${name}<span class="count">${count(id)}</span></button>`).join('');
 const rows=state.orders.filter(o=>(state.kdsFilter==='all'||(state.kdsFilter==='active'?['pending','accepted','preparing','ready'].includes(o.status):o.status===state.kdsFilter))&&(!state.kdsSearch||(o.number+' '+o.name).toLowerCase().includes(state.kdsSearch.toLowerCase())));
 $('#order-grid').innerHTML=rows.length?rows.map(orderCard).join(''):'<div class="empty" style="grid-column:1/-1"><h3>目前沒有這類訂單</h3><p>新訂單會出現在這裡，不必一直重新整理。</p></div>';
 $('#order-pagination').innerHTML=state.orderTotal>100?`<div class="pagination"><button class="btn outline small" data-action="orders-prev" ${state.offset===0?'disabled':''}>上一頁</button><span>第 ${Math.floor(state.offset/100)+1} 頁，共 ${state.orderTotal} 筆；分類數量為本頁統計</span><button class="btn outline small" data-action="orders-next" ${state.offset+100>=state.orderTotal?'disabled':''}>下一頁</button></div>`:'';
}
function orderCard(o){
 const role=state.user.role,minor=role!=='kitchen';let actions='';
 const action=(a,t,css='')=>`<button class="btn small ${css}" data-action="order-action" data-id="${o.public_id}" data-command="${a}">${t}</button>`;
 if(o.status==='pending'){actions+=action('accept','接單');if(minor)actions+=action('reject','無法接單','outline minor')}
 if(o.status==='accepted')actions+=action('prepare','開始製作');
 if(o.status==='preparing')actions+=action('ready','餐點完成，通知取餐');
 if(o.status==='ready'&&minor){if(o.payment==='unpaid')actions+=action('pay','確認收現金 '+money(o.total));else if(o.payment==='paid')actions+=action('complete','確認交付餐點')}
 if(o.status==='ready'&&!minor)actions+='<span class="help">待櫃台確認收款與交付</span>';
 const late=new Date(o.day+'T'+o.slot+':00+08:00')<new Date()&&['accepted','preparing'].includes(o.status);
 const pending= Math.max(0,Math.ceil((new Date(o.expires_at)-new Date())/60000));
 return `<article class="order-card"><div class="order-head"><span class="number mono">${esc(o.number)}</span><span class="badge ${o.status}">${statusNames[o.status]}</span></div><div class="order-body"><div class="order-meta"><span class="${late?'late':''}">${o.slot} 取餐${late?' · 已到預約時間':''}</span><span>${esc(o.name)} · ${o.portions} 份</span></div>${o.status==='pending'?`<p class="help ${pending<=3?'late':''}">${clock(o.expires_at)} 前接單 · 剩約 ${pending} 分鐘</p>`:''}<ul class="order-items">${o.items.map(i=>`<li><strong>${esc(i.name)} × ${i.quantity}</strong><small>${esc(i.labels.join(' / '))}${i.note?' · '+esc(i.note):''}</small></li>`).join('')}</ul>${o.note?`<div class="order-note">訂單備註：${esc(o.note)}</div>`:''}${o.phone&&minor?`<div class="help">聯絡電話：<a href="tel:${esc(o.phone)}">${esc(o.phone)}</a></div>`:''}</div><div class="order-footer"><div class="between"><strong>${money(o.total)}</strong><span class="help">${o.payment==='paid'?'已收現金':o.payment==='refunded'?'已退還現金':'未收款'}</span></div>${actions?`<div class="order-actions">${actions}</div>`:''}<div class="order-tools">${!preview?`<a href="/api/staff/receipt/${o.public_id}" target="_blank" rel="noopener">列印取餐單</a>`:''}<button data-action="order-detail" data-id="${o.public_id}">紀錄</button>${minor&&['accepted','preparing','ready'].includes(o.status)&&o.payment==='unpaid'?`<button data-action="order-action" data-id="${o.public_id}" data-command="cancel">取消</button>`:''}${minor&&o.status==='ready'&&o.payment==='unpaid'?`<button data-action="order-action" data-id="${o.public_id}" data-command="no_show">未取餐</button>`:''}${role==='owner'&&o.payment==='paid'?`<button data-action="order-action" data-id="${o.public_id}" data-command="refund">退現金</button>`:''}</div></div></article>`;
}
async function orderAction(id,command){
 const o=state.orders.find(x=>x.public_id===id);if(!o)return;
 if(['pay','refund','cancel','reject','no_show'].includes(command)){
  const titles={pay:'確認已收到現金',refund:'確認現金已退還',cancel:'取消訂單',reject:'無法接受訂單',no_show:'標記未取餐'};
  openDialog(`<form id="action-form" data-id="${id}" data-command="${command}" data-version="${o.version}">${modalHead(titles[command],o.number)}<div class="modal-body"><p>${esc(o.name)} · ${o.portions} 份 · <strong>${money(o.total)}</strong></p>${['pay','refund'].includes(command)?`<div class="notice">此按鈕只登記帳款，不會從任何帳戶扣款或自動退款。請先${command==='pay'?'實際收妥':'實際退還'}現金。</div><label class="check"><input name="confirm_cash" type="checkbox" required><span>我確認現金 ${money(o.total)} 已${command==='pay'?'收到':'交還顧客'}。</span></label>`:''}${command!=='pay'?'<label class="field" style="margin-top:18px"><span>處理原因（會顯示在顧客的訂單紀錄）</span><input name="reason" required maxlength="120" placeholder="請清楚說明原因"></label>':''}${['preparing','ready','completed'].includes(o.status)?'<p class="help" style="margin-top:18px">已進入製作流程，取消或退款不會自動回補食材庫存。</p>':''}<p class="error-text" id="dialog-error"></p></div><div class="modal-foot"><button type="button" class="btn outline" data-action="close">返回</button><button type="submit" class="btn ${command==='pay'?'':'danger'}">確認${command==='pay'?'收款':'處理'}</button></div></form>`);
 }else{await api(`/api/staff/orders/${id}/action`,'POST',{action:command,version:o.version,reason:'',confirm_cash:false});await refreshOrders();toast('訂單已更新')}
}
function renderInventory(){const owner=state.user.role==='owner';$('#staff-content').innerHTML=`<div class="toolbar"><h2 style="margin:0;font-size:20px">菜單與庫存</h2><div class="spacer"></div><label class="help">庫存日期</label><input type="date" id="inventory-day" value="${state.staffDay}" min="${state.store.today}" max="${dayPlus(state.store.today,7)}" aria-label="庫存日期">${owner?'<button class="btn small" data-action="new-product">新增餐點 ＋</button>':''}<button class="btn outline small" data-action="refresh-staff">重新整理</button></div><div class="notice">「剩餘庫存」是選定取餐日可再接的份數；「每日預設量」只用於尚未建立庫存紀錄的日期。已接單會立即扣庫存。</div><div class="panel table-wrap"><table><thead><tr><th>餐點</th><th>價格</th><th>當日可售</th><th>每日預設量</th><th>狀態</th><th>操作</th></tr></thead><tbody>${state.staffProducts.map(p=>`<tr><td><strong>${esc(p.name)}</strong><span class="sub">${esc(p.category)}</span></td><td>${money(p.price)}</td><td><strong class="${p.remaining<=5?'late':''}">${p.remaining} 份</strong></td><td>${p.daily_stock} 份</td><td><span class="badge ${!p.active||p.sold_out?'cancelled':''}">${!p.active?'已下架':p.sold_out?'暫停供應':'供應中'}</span></td><td><div class="flex"><button class="btn outline small" data-action="stock" data-id="${p.id}">調整庫存</button>${owner?`<button class="btn secondary small" data-action="edit-product" data-id="${p.id}">編輯餐點</button>`:''}</div></td></tr>`).join('')}</tbody></table></div><p class="help">本系統管理餐點份數，不是原物料採購或多店共享庫存系統。</p>`}
function openStock(id){const p=state.staffProducts.find(x=>x.id===id);openDialog(`<form id="stock-form" data-id="${id}" data-expected="${p.remaining}">${modalHead('調整剩餘庫存',p.name)}<div class="modal-body"><div class="notice">${displayDate(state.staffDay)} · 目前可售 ${p.remaining} 份</div><label class="field"><span>調整後可再接的份數</span><input name="remaining" type="number" min="0" max="2000" value="${p.remaining}" required></label><label class="field"><span>原因</span><input name="reason" maxlength="100" required placeholder="例如：臨時加備 10 份／現場已售完"></label><p class="help">填 0 即當日售完。這裡填的是「剩餘」份數，不是今日總準備量；已接訂單不會被取消。</p><p id="dialog-error" class="error-text"></p></div><div class="modal-foot"><button class="btn" type="submit">儲存庫存</button></div></form>`)}
function openEditProduct(id){
 const p=state.staffProducts.find(x=>x.id===id)||{id:'',name:'',description:'',category:'肉類餐盒',price:130,daily_stock:30,active:true,sold_out:false,options:[],kind:'meal',version:0};state.editProduct=p;
 openDialog(`<form id="edit-product-form">${modalHead(p.id?'編輯餐點':'新增餐點')}<div class="modal-body"><label class="field"><span>餐點名稱</span><input name="name" value="${esc(p.name)}" maxlength="60" required></label><label class="field"><span>餐點說明</span><textarea name="description" maxlength="240">${esc(p.description)}</textarea></label><div class="field-grid"><label class="field"><span>價格（新台幣）</span><input name="price" type="number" min="1" max="3000" value="${p.price}" required></label><label class="field"><span>每日預設份數</span><input name="daily_stock" type="number" min="0" max="2000" value="${p.daily_stock}" required></label></div><div class="field-grid" style="margin-top:17px"><label class="field"><span>分類</span><input name="category" value="${esc(p.category)}" maxlength="24" required></label><label class="field"><span>品項類型</span><select name="kind"><option value="meal" ${p.kind==='meal'?'selected':''}>餐盒</option><option value="addon" ${p.kind==='addon'?'selected':''}>加點</option></select></label></div><div class="flex" style="margin-top:20px"><label class="check"><input name="active" type="checkbox" ${p.active?'checked':''}><span>上架供應</span></label><label class="check"><input name="sold_out" type="checkbox" ${p.sold_out?'checked':''}><span>暫停供應（所有日期）</span></label></div><div class="divider"></div><h3>客製選項</h3>${p.options.map((g,gi)=>`<div class="spec-edit"><label class="check"><input type="checkbox" name="keep-${gi}" checked><span>保留「${esc(g.name)}」</span></label>${g.choices.map((c,ci)=>`<div class="field-grid"><label class="field"><span>${ci===0?'選項名稱':''}</span><input name="choice-name-${gi}-${ci}" value="${esc(c.name)}" maxlength="24" required></label><label class="field"><span>${ci===0?'加價（元）':''}</span><input name="choice-price-${gi}-${ci}" type="number" min="0" max="1000" value="${c.price}" required></label></div>`).join('')}</div>`).join('')}<label class="field"><span>加入常用選項</span><select name="new-option"><option value="">不新增</option>${!p.options.some(g=>g.id==='rice')?'<option value="rice">飯量：正常飯／半飯／飯換菜（預設不加價）</option>':''}${!p.options.some(g=>g.id==='spicy')?'<option value="spicy">辣度：小辣／中辣／大辣</option>':''}</select></label><p class="help">更改售價或規格會要求尚未送出的舊購物車重新確認；已成立的訂單保留原金額。</p><p class="error-text" id="dialog-error"></p></div><div class="modal-foot"><button class="btn" type="submit">儲存餐點</button></div></form>`);
}
function renderReports(){const r=state.report;$('#staff-content').innerHTML=`<div class="toolbar"><h2 style="margin:0;font-size:20px">營業報表</h2><div class="spacer"></div><input type="date" id="report-day" value="${state.staffDay}" aria-label="報表日期"><button class="btn outline small" data-action="export">匯出訂單 CSV</button></div><div class="metrics"><div class="metric"><p>今日淨收現金</p><strong>${money(r.net_cash)}</strong><small>按收／退款發生日期計算</small></div><div class="metric"><p>已完成餐點金額</p><strong>${money(r.completed_total)}</strong><small>取餐日已交付且未退款</small></div><div class="metric"><p>取餐日訂單</p><strong>${r.orders}<span style="font-size:15px"> 筆</span></strong><small>包含取消及未完成訂單</small></div><div class="metric"><p>今日現金退款</p><strong>${money(r.cash_refunded)}</strong><small>只統計已確認退還的現金</small></div></div><div class="panel"><h2>餐點銷售份數</h2><p class="help">僅計已完成且未退款的訂單，不把待接單當成營收。</p>${r.products.length?r.products.map(p=>`<div class="bar-row"><span>${esc(p.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(3,p.quantity/Math.max(...r.products.map(x=>x.quantity))*100)}%"></div></div><strong class="mono">${p.quantity} 份</strong></div>`).join(''):'<div class="empty">這一天尚無已完成餐點。</div>'}</div><div class="panel"><h2>訂單處理結果</h2><div class="flex wrap">${Object.entries(r.states).map(([k,v])=>`<span class="badge ${k}">${statusNames[k]} ${v}</span>`).join('')}</div></div>`}
function renderSettings(){const s=state.store;$('#staff-content').innerHTML=`<form id="settings-form" class="settings-form"><div class="notice">${s.mode==='demo'?'目前 APP_MODE=demo；即使勾選資料已確認，仍然是測試環境。正式啟用需由主機管理者設定 live 模式、HTTPS 與專用資料庫。':'修改營業時間不會取消已存在的預約；有異動請主動聯繫受影響顧客。'}</div><div class="panel"><h2>店家資訊</h2><div class="form-grid"><label class="field"><span>店名</span><input name="name" maxlength="60" required value="${esc(s.name)}"></label><label class="field"><span>分店名稱</span><input name="branch" maxlength="60" required value="${esc(s.branch)}"></label><label class="field wide"><span>地址</span><input name="address" maxlength="120" required value="${esc(s.address)}"></label><label class="field"><span>聯絡電話</span><input name="phone" maxlength="24" required value="${esc(s.phone)}"></label><label class="field wide"><span>顧客首頁公告</span><textarea name="announcement" maxlength="240">${esc(s.announcement)}</textarea></label></div></div><div class="panel"><h2>接單規則</h2><div class="form-grid">${[['prep_minutes','最短備餐時間（分鐘）',5,120],['slot_capacity','每時段最多可接份數',1,200],['advance_days','可提前預約天數',0,7],['accept_timeout','未接單自動取消（分鐘）',2,30],['privacy_days','個資保留天數',7,90]].map(([key,label,min,max])=>`<label class="field"><span>${label}</span><input name="${key}" type="number" min="${min}" max="${max}" value="${s[key]}" required></label>`).join('')}<label class="field"><span>取餐時段間隔</span><select name="slot_minutes">${[10,15,20,30].map(x=>`<option value="${x}" ${s.slot_minutes===x?'selected':''}>${x} 分鐘</option>`).join('')}</select></label></div><label class="check"><input name="paused" type="checkbox" ${s.paused?'checked':''}><span>暫停接受新訂單（已接訂單不受影響）</span></label></div><div class="panel"><h2>每週取餐時間</h2><p class="help">填寫方式：11:00-14:00,17:00-20:00。空白代表休息。跨日營業暫不支援；星期以台灣時間計算。</p>${['週一','週二','週三','週四','週五','週六','週日'].map((d,i)=>`<label class="hours-row"><span>${d}</span><input name="hours-${i}" value="${esc(s.hours[i].map(v=>v.join('-')).join(','))}" placeholder="休息"></label>`).join('')}<label class="field" style="margin-top:20px"><span>臨時店休日</span><input name="closed_dates" value="${esc(s.closed_dates.join(','))}" placeholder="2026-10-10,2026-10-11"><small>使用 YYYY-MM-DD，多個日期以逗號分隔。</small></label></div><div class="panel"><h2>正式資料確認</h2><label class="check"><input name="verified" type="checkbox" ${s.verified?'checked':''}><span>店家已確認菜單名稱、所有價格、客製加價、營業時間、庫存上限、付款與個資告知內容；不是沿用未確認的測試資料。</span></label><p class="help" style="margin-top:14px">店家須先同意使用系統。請勿擅自以店家名義收款或宣稱已正式接單。</p></div><div class="flex wrap"><button type="submit" class="btn">儲存營業設定</button>${!preview?'<button type="button" class="btn outline" data-action="shop-qr">點餐入口 QR Code</button>':''}<button type="button" class="btn outline" data-action="password">變更自己的密碼</button></div><p class="error-text" id="settings-error"></p></form>`}
function renderUsers(){$('#staff-content').innerHTML=`<div class="toolbar"><h2 style="margin:0;font-size:20px">人員與權限</h2><div class="spacer"></div><button class="btn small" data-action="new-user">新增店員 ＋</button></div><div class="panel table-wrap"><table><thead><tr><th>姓名／帳號</th><th>角色</th><th>狀態</th><th>操作</th></tr></thead><tbody>${state.staffUsers.map(u=>`<tr><td>${esc(u.name)}<span class="sub">${esc(u.username)}</span></td><td>${roleNames[u.role]}</td><td>${u.active?'啟用':'已停用'}</td><td>${u.role!=='owner'?`<button class="btn outline small" data-action="edit-user" data-id="${u.id}">帳號設定</button>`:'管理者請使用變更密碼'}</td></tr>`).join('')}</tbody></table></div><div class="panel"><h2>權限分工</h2><p class="help">管理者：完整菜單、接單、帳款退款、報表、人員與設定。<br>櫃台：接單、交付、收款、調整剩餘庫存與暫停接單；不可退款或更改售價。<br>廚房：查看製作需求、接單、開始製作與標記餐點完成；不提供完整聯絡電話、收款或營業報表。</p></div>`}
function openUser(id){const u=state.staffUsers?.find(x=>x.id===Number(id));openDialog(`<form id="${u?'user-update-form':'user-form'}" ${u?`data-id="${u.id}"`:''}>${modalHead(u?'店員帳號設定':'新增店員')}<div class="modal-body">${u?`<p>${esc(u.name)} · ${esc(u.username)} · ${roleNames[u.role]}</p><label class="check"><input type="checkbox" name="active" ${u.active?'checked':''}><span>允許登入</span></label><label class="field" style="margin-top:17px"><span>重設密碼（留白代表不變更）</span><input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password"></label>`:`<label class="field"><span>稱呼</span><input name="name" maxlength="24" required></label><label class="field"><span>登入帳號（英數、底線或連字號）</span><input name="username" pattern="[a-zA-Z0-9_-]{3,32}" required autocomplete="off"></label><label class="field"><span>角色</span><select name="role"><option value="cashier">櫃台</option><option value="kitchen">廚房</option></select></label><label class="field"><span>密碼（至少 12 個字元）</span><input name="password" type="password" minlength="12" maxlength="128" required autocomplete="new-password"></label>`}<p class="help">請一人一個帳號。停用或重設密碼後，該帳號所有裝置都會登出。</p><p class="error-text" id="dialog-error"></p></div><div class="modal-foot"><button class="btn" type="submit">儲存</button></div></form>`)}
function renderAudit(events){$('#staff-content').innerHTML=`<div class="toolbar"><h2 style="margin:0;font-size:20px">操作紀錄</h2><div class="spacer"></div><button class="btn outline small" data-action="refresh-staff">重新整理</button></div><div class="panel">${events.length?events.map(e=>`<div class="audit-row"><span class="muted">${esc(e.created_at.slice(0,10))} ${clock(e.created_at)}</span><span>${esc(e.actor||'顧客／系統')}<br><small class="muted">${esc(e.number||'')}</small></span><div><strong>${esc(e.action)}</strong><br>${esc(e.detail)}</div></div>`).join(''):'<p class="help">尚無紀錄</p>'}</div><div class="pagination"><button class="btn outline small" data-action="audit-prev" ${state.auditOffset===0?'disabled':''}>上一頁</button><span>第 ${Math.floor(state.auditOffset/100)+1} 頁</span><button class="btn outline small" data-action="audit-next" ${events.length<100?'disabled':''}>下一頁</button></div>`}
async function loadDisplay(){document.body.classList.add('display-mode');document.title='取餐看板 · 穀穀';const data=await api('/api/board');$('#app').innerHTML=`${demoBanner()}<header class="display-header"><a class="brand" href="${link('shop')}"><div class="brand-mark">穀</div><div><strong>${esc(state.store.name)}</strong><span>${esc(state.store.branch)} · 取餐看板</span></div></a><span class="mono muted" id="board-time">${clock(data.time)}</span></header><main class="display-main" id="main"><div class="display-grid"><section class="display-ready"><h1>這幾餐，已經準備好了。</h1><p>請到櫃台報號，確認付款後取餐。</p><div class="display-numbers" id="ready-numbers"></div></section><section class="display-working"><h2>正在為你準備</h2><p class="muted">新鮮現做，再等我們一下。</p><div class="display-numbers" id="working-numbers"></div></section></div><p class="help" id="connection" style="margin-top:20px"><i class="status-dot"></i>${preview?'本機體驗・不顯示真實店家訂單':'每 3 秒更新 · 不顯示顧客姓名或電話'}</p></main>`;renderBoard(data)}
function renderBoard(data){if(!$('#ready-numbers'))return;const ready=data.orders.filter(o=>o.status==='ready'),working=data.orders.filter(o=>o.status!=='ready');$('#board-time').textContent=clock(data.time);$('#ready-numbers').innerHTML=ready.length?ready.map(o=>`<div class="display-number mono">${esc(o.number)}</div>`).join(''):'<p style="grid-column:1/-1;color:#c5d1bb">餐點完成後，號碼會顯示在這裡。</p>';$('#working-numbers').innerHTML=working.length?working.map(o=>`<div class="display-number mono">${esc(o.number)}</div>`).join(''):'<p class="help" style="grid-column:1/-1">目前沒有製作中的餐點。</p>'}
let audioContext;
function beep(){try{audioContext=audioContext||new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.frequency.setValueAtTime(760,audioContext.currentTime);gain.gain.setValueAtTime(.07,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.45);oscillator.start();oscillator.stop(audioContext.currentTime+.5)}catch{toast('瀏覽器無法播放提示音，請留意工作台畫面')}}
function mobileCart(){openDialog(`<div id="mobile-cart-dialog">${modalHead('這一餐')}<div class="modal-body">${state.cart.length?cartRows():'<div class="empty">購物車是空的。</div>'}<div class="cart-total"><span>共 ${cartQty()} 份</span><strong>${money(cartTotal())}</strong></div></div><div class="modal-foot"><button class="btn" data-action="checkout" ${!state.cart.length?'disabled':''}>選擇時間，確認訂單 →</button></div></div>`)}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('已複製，請私下保存，不要公開分享')}catch{openDialog(`${modalHead('複製訂單連結')}<div class="modal-body"><label class="field"><span>長按或全選後複製</span><input readonly value="${esc(text)}"></label></div>`)}}
function passwordDialog(){if(preview)return toast('體驗版不保存密碼；正式系統會要求目前密碼並撤銷舊登入');openDialog(`<form id="password-form">${modalHead('變更自己的密碼')}<div class="modal-body"><label class="field"><span>目前密碼</span><input name="current_password" type="password" autocomplete="current-password" required></label><label class="field"><span>新密碼（至少 12 字元）</span><input name="new_password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><p class="help">更改後會登出所有裝置，請使用新密碼登入。</p><p class="error-text" id="dialog-error"></p></div><div class="modal-foot"><button class="btn" type="submit">更新密碼並登出</button></div></form>`)}
async function showQr(type){let url;if(type==='shop')url='/api/staff/ordering-qr';else{const r=await fetch('/api/order/qr',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Requested-With':'Gugu'},body:JSON.stringify({token:state.trackToken})});if(!r.ok)throw new Error('QR Code 暫時無法產生');url=URL.createObjectURL(await r.blob())}openDialog(`${modalHead(type==='shop'?'顧客點餐入口':'私人訂單查詢憑證')}<div class="modal-body"><img src="${esc(url)}" alt="${type==='shop'?'點餐入口':'私人訂單查詢'} QR Code" class="qr-image"><p class="help">${type==='shop'?'公開網址取自 PUBLIC_ORIGIN；localhost 網址不能讓其他手機遠端存取。正式張貼前，請先用店外行動網路測試。':'此 QR Code 含私人訂單查詢權限，請勿公開張貼。店員仍須核對取餐號碼與付款狀態。'}</p></div>`);if(type!=='shop')$('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true})}
document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;
 if(a==='close'&&el.tagName==='A'){closeDialog();return}
 event.preventDefault();
 try{
  if(a==='reload'){location.reload();return}
  if(a==='close'){closeDialog();return}
  if(a==='privacy'){openDialog(`${modalHead('訂購與個資說明')}<div class="modal-body"><p class="help">${privacySummary()}</p></div>`);return}
  if(a==='recent'){showRecent();return}
  if(a==='category'){state.category=el.dataset.value;renderCategories();renderMenu();return}
  if(a==='product'){openProduct(el.dataset.id);return}
  if(a==='product-minus'||a==='product-plus'){const n=$('#product-qty');n.textContent=Math.min(20,Math.max(1,Number(n.textContent)+(a==='product-plus'?1:-1)));updateProductPrice();return}
  if(a.startsWith('cart-')){if(state.pendingOrder)throw new Error('送單結果尚未確認，請先處理同一筆訂單');const n=Number(el.dataset.index),i=state.cart[n];if(!i)return;if(a==='cart-remove'||a==='cart-minus'&&i.quantity===1)state.cart.splice(n,1);else if(a==='cart-minus')i.quantity--;else if(a==='cart-plus'){if(i.quantity>=20||cartQty()>=40)throw new Error('單一組合最多 20 份，整筆最多 40 份');i.quantity++}saveCart();if($('#mobile-cart-dialog'))mobileCart();return}
  if(a==='mobile-cart'){mobileCart();return}
  if(a==='checkout'){await openCheckout();return}
  if(a==='retry-order'){await retryOrder();return}
  if(a==='refresh-track'){await loadTrack();return}
  if(a==='copy-order'){await copyText(preview?location.href:location.origin+'/#order='+state.trackToken);return}
  if(a==='order-qr'){await showQr('order');return}
  if(a==='shop-qr'){await showQr('shop');return}
  if(a==='cancel-order'){openDialog(`<form id="customer-cancel-form">${modalHead('取消這筆訂單？',state.track.number)}<div class="modal-body"><p>僅能在店家接單前取消。確認取消後，系統會釋出預留餐點與取餐容量。</p><p id="dialog-error" class="error-text"></p></div><div class="modal-foot"><button class="btn outline" type="button" data-action="close">保留訂單</button><button class="btn danger" type="submit">確定取消</button></div></form>`);return}
  if(a==='logout'){await api('/api/auth/logout','POST',{});state.user=null;state.csrf='';renderLogin();return}
  if(a==='password'){passwordDialog();return}
  if(a==='staff-tab'){state.staffTab=el.dataset.tab;await loadStaffTab();return}
  if(a==='refresh-staff'){await loadStaffTab();return}
  if(a==='queue-date'){state.staffDay=el.dataset.day;state.offset=0;await loadStaffTab();return}
  if(a==='kds-filter'){state.kdsFilter=el.dataset.value;renderOrders();return}
  if(a==='sound'){state.sound=!state.sound;$('#sound-button').textContent=state.sound?'提示音已開啟':'開啟新單提示音';if(state.sound)beep();return}
  if(a==='pause'){state.store=await api('/api/store');await api('/api/staff/pause','POST',{paused:!state.store.paused,version:state.store.version});state.store=await api('/api/store');await loadStaffTab();toast(state.store.paused?'已暫停新訂單；既有訂單不受影響':'已恢復接單');return}
  if(a==='order-action'){el.disabled=true;await orderAction(el.dataset.id,el.dataset.command);el.disabled=false;return}
  if(a==='order-detail'){const o=state.orders.find(o=>o.public_id===el.dataset.id);openDialog(`${modalHead('訂單處理紀錄',o.number)}<div class="modal-body"><ul class="timeline">${o.events.map(e=>`<li><strong>${esc(e.detail||e.action)}</strong>${clock(e.at)}</li>`).join('')}</ul></div>`);return}
  if(a==='orders-prev'||a==='orders-next'){state.offset=Math.max(0,state.offset+(a==='orders-next'?100:-100));await refreshOrders();return}
  if(a==='stock'){openStock(el.dataset.id);return}
  if(a==='new-product'){openEditProduct('');return}
  if(a==='edit-product'){openEditProduct(el.dataset.id);return}
  if(a==='new-user'){openUser();return}
  if(a==='edit-user'){openUser(el.dataset.id);return}
  if(a==='audit-prev'||a==='audit-next'){state.auditOffset=Math.max(0,state.auditOffset+(a==='audit-next'?100:-100));await loadStaffTab();return}
  if(a==='export'){
   if(!preview){const anchor=document.createElement('a');anchor.href='/api/staff/export?day='+state.staffDay;anchor.download='gugu-orders.csv';anchor.click()}
   else{const csv=await api('/api/staff/export?day='+state.staffDay);download(csv.csv,'gugu-demo-orders.csv','text/csv;charset=utf-8')}
   return;
  }
 }catch(e){el.disabled=false;const out=$('#dialog-error');if(out)out.textContent=e.message;else toast(e.message);if(e.status===401&&state.area==='staff'){closeDialog();renderLogin()}}
});
document.addEventListener('input',event=>{
 if(event.target.id==='menu-search'){state.search=event.target.value;renderMenu()}
 if(event.target.id==='order-search'){state.kdsSearch=event.target.value;renderOrders()}
});
document.addEventListener('change',async event=>{
 try{
  if(event.target.closest('#product-form')&&event.target.type==='radio')updateProductPrice();
  if(event.target.id==='pickup-day'){state.day=event.target.value;await loadShop()}
  if(['staff-day','inventory-day','report-day'].includes(event.target.id)){state.staffDay=event.target.value;state.offset=0;await loadStaffTab()}
 }catch(e){toast(e.message)}
});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!form.id)return;event.preventDefault();
 const submit=form.querySelector('button[type=submit]');if(submit?.disabled)return;
 if(submit)submit.disabled=true;
 const f=new FormData(form),str=k=>String(f.get(k)||''),num=k=>Number(f.get(k)),check=k=>f.get(k)==='on';
 try{
  if(form.id==='product-form')addProduct(form);
  if(form.id==='checkout-form')await submitOrder(form);
  if(form.id==='customer-cancel-form'){state.track=await api('/api/order/cancel','POST',{token:state.trackToken,version:state.track.version});closeDialog();renderTrack(state.track);toast('訂單已取消')}
  if(form.id==='login-form'){
   const result=await api('/api/auth/login','POST',preview?{username:str('role'),password:'preview-only'}:{username:str('username'),password:str('password')});
   state.user=result.user;state.csrf=result.csrf;state.staffTab='orders';renderStaffShell();await loadStaffTab();
  }
  if(form.id==='action-form'){await api(`/api/staff/orders/${form.dataset.id}/action`,'POST',{action:form.dataset.command,version:Number(form.dataset.version),reason:str('reason'),confirm_cash:check('confirm_cash')});closeDialog();await refreshOrders();toast('訂單處理完成')}
  if(form.id==='stock-form'){await api('/api/staff/stock','POST',{day:state.staffDay,product_id:form.dataset.id,remaining:num('remaining'),expected_remaining:Number(form.dataset.expected),reason:str('reason')});closeDialog();await loadStaffTab();toast('庫存已更新')}
  if(form.id==='edit-product-form'){
   const p=state.editProduct;const options=p.options.filter((g,gi)=>check('keep-'+gi)).map(g=>{const gi=p.options.indexOf(g);return{...g,choices:g.choices.map((c,ci)=>({...c,name:str(`choice-name-${gi}-${ci}`),price:num(`choice-price-${gi}-${ci}`)}))}});
   if(str('new-option')==='rice')options.push({id:'rice',name:'飯量',required:true,choices:[{id:'normal',name:'正常飯',price:0},{id:'half',name:'半飯',price:0},{id:'veg',name:'飯換菜',price:0}]});
   if(str('new-option')==='spicy')options.push({id:'spicy',name:'辣度',required:true,choices:[{id:'mild',name:'小辣',price:0},{id:'medium',name:'中辣',price:0},{id:'hot',name:'大辣',price:0}]});
   await api('/api/staff/products','POST',{id:p.id||'dish-'+uid().slice(0,12),name:str('name'),description:str('description'),category:str('category'),price:num('price'),daily_stock:num('daily_stock'),active:check('active'),sold_out:check('sold_out'),kind:str('kind'),options,version:p.version});
   closeDialog();await loadStaffTab();toast('餐點已儲存');
  }
  if(form.id==='settings-form'){
   const data={version:state.store.version};for(const k of ['name','branch','address','phone','announcement'])data[k]=str(k);
   for(const k of ['prep_minutes','slot_minutes','slot_capacity','advance_days','accept_timeout','privacy_days'])data[k]=num(k);
   data.paused=check('paused');data.verified=check('verified');data.closed_dates=str('closed_dates').split(/[,，]/).map(x=>x.trim()).filter(Boolean);data.hours={};
   for(let i=0;i<7;i++)data.hours[i]=str('hours-'+i).split(/[,，]/).map(x=>x.trim()).filter(Boolean).map(x=>x.split('-').map(t=>t.trim()));
   await api('/api/staff/settings','POST',data);state.store=await api('/api/store');renderSettings();toast('營業設定已更新');
  }
  if(form.id==='user-form'){await api('/api/staff/users','POST',{username:str('username'),name:str('name'),role:str('role'),password:str('password')});closeDialog();await loadStaffTab();toast('店員帳號已建立')}
  if(form.id==='user-update-form'){await api('/api/staff/users/'+form.dataset.id,'POST',{active:check('active'),password:str('password')||null});closeDialog();await loadStaffTab();toast('帳號已更新，舊登入已撤銷')}
  if(form.id==='password-form'){await api('/api/auth/password','POST',{current_password:str('current_password'),new_password:str('new_password')});closeDialog();state.user=null;state.csrf='';renderLogin();toast('密碼已更新，請重新登入')}
 }catch(e){const out=$('#dialog-error')||$('#login-error')||$('#settings-error');if(out){out.textContent=e.message;out.scrollIntoView({block:'nearest'})}else toast(e.message)}finally{if(submit?.isConnected)submit.disabled=false}
});
function download(content,filename,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
window.addEventListener('hashchange',()=>route().catch(e=>toast(e.message)));
window.addEventListener('online',()=>{connection(true);toast('網路已恢復；未確認訂單請使用原筆重試')});
window.addEventListener('offline',()=>connection(false));
setInterval(async()=>{
 if(document.hidden||refreshing||!state.store)return;
 refreshing=true;
 try{
  if(state.area==='track'&&state.trackToken){const o=await api('/api/order/track','POST',{token:state.trackToken});if(!state.track||o.version!==state.track.version){state.track=o;const t=$('#ticket-content');if(t)t.innerHTML=trackContents(o)}connection(true)}
 }catch(e){connection(false);if(e.status===401&&state.area==='staff'){state.user=null;closeDialog();renderLogin()}}
 finally{refreshing=false}
},5000);
// Separate 3-second refresh for staff / board avoids relying on browser notifications.
setInterval(async()=>{if(document.hidden||refreshing||!state.store)return;if(state.area!=='display'&&!(state.area==='staff'&&state.user&&state.staffTab==='orders'))return;refreshing=true;try{if(state.area==='display')renderBoard(await api('/api/board'));else await refreshOrders()}catch(e){connection(false);if(e.status===401){state.user=null;closeDialog();renderLogin()}}finally{refreshing=false}},3000);
init();
